create or replace function public.issue_black_card_for_ticket() returns trigger language plpgsql security definer set search_path to 'public' as $function$ declare code text; n bigint; begin select tp.code into code from public.ticket_products tp where tp.id=new.ticket_product_id; if code='black_card' then n:=nextval('public.black_card_number_seq'); if n>70 then raise exception 'black_card_sold_out'; end if; insert into public.black_cards(ticket_id,profile_id,card_number,valid_from,valid_until) values(new.id,new.profile_id,'2026-'||to_char(n,'FM0000'),now(),now()+interval '1 year') on conflict(ticket_id) do nothing; end if; return new; end $function$;
